pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);

        // Attacker picks the answer that the mutant produces for any settle call:
        // blockhash(block.number) == 0, so answer = keccak256(abi.encodePacked(bytes32(0))).
        bytes32 forcedAnswer = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 2 ether);
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(forcedAnswer);
        vm.stopPrank();

        vm.roll(block.number + 2);

        vm.prank(actor);
        c.settle();

        // Reference: the answer derives from the locked block hash, so the forced
        // constant guess cannot match; attacker loses 1 ether.
        // Mutant: the answer is that same constant, so attacker wins 2 ether.
        assertTrue(address(actor).balance != 0 ether);
    }
}
